class Solution {
public:
    int sumOfPowers(vector<int>& nums, int k) {
        const long long MOD = 1e9 + 7;
        int n = nums.size();
        sort(nums.begin(), nums.end());
        vector<vector<long long>> C(n + 1, vector<long long>(k + 1, 0));
        for (int i = 0; i <= n; i++) {
            C[i][0] = 1;
            for (int j = 1; j <= min(i, k); j++)
                C[i][j] = (C[i - 1][j - 1] + C[i - 1][j]) % MOD;
        }
        long long ans = 0;
        for (int i = 0; i < n; i++)
            for (int j = i + 1; j < n; j++) {
                long long g = nums[j] - nums[i];
                int L = lower_bound(nums.begin(), nums.begin() + i, nums[i] - g) - nums.begin();
                int s = lower_bound(nums.begin(), nums.end(), nums[j] + g) - nums.begin();
                ans = (ans + g % MOD * C[L + n - s][k - 2]) % MOD;
            }
        return ans;
    }
};

