class Solution {
    public int sumOfPowers(int[] nums, int k) {
        final long MOD = 1_000_000_007L;
        int n = nums.length;
        Arrays.sort(nums);
        long[][] C = new long[n + 1][k + 1];
        for (int i = 0; i <= n; i++) {
            C[i][0] = 1;
            for (int j = 1; j <= Math.min(i, k); j++)
                C[i][j] = (C[i - 1][j - 1] + C[i - 1][j]) % MOD;
        }
        long ans = 0;
        for (int i = 0; i < n; i++)
            for (int j = i + 1; j < n; j++) {
                long g = nums[j] - nums[i];
                int L = lowerBound(nums, 0, i, nums[i] - g);
                int s = lowerBound(nums, 0, n, nums[j] + g);
                ans = (ans + g % MOD * C[L + n - s][k - 2]) % MOD;
            }
        return (int) ans;
    }
    private int lowerBound(int[] a, int lo, int hi, long v) {
        int l = lo, r = hi;
        while (l < r) { int m = (l + r) >>> 1; if (a[m] < v) l = m + 1; else r = m; }
        return l;
    }
}

