var sumOfPowers = function(nums, k) {
    const MOD = 1e9 + 7;
    nums.sort((a, b) => a - b);
    const n = nums.length;
    const C = Array.from({ length: n + 1 }, () => new Array(k + 1).fill(0));
    for (let i = 0; i <= n; i++) {
        C[i][0] = 1;
        for (let j = 1; j <= Math.min(i, k); j++)
            C[i][j] = (C[i - 1][j - 1] + C[i - 1][j]) % MOD;
    }
    const lb = (v, hi) => { let l = 0, r = hi;
        while (l < r) { const m = (l + r) >> 1; if (nums[m] < v) l = m + 1; else r = m; } return l; };
    let ans = 0;
    for (let i = 0; i < n; i++)
        for (let j = i + 1; j < n; j++) {
            const g = nums[j] - nums[i];
            const L = lb(nums[i] - g, i);
            const s = lb(nums[j] + g, n);
            ans = (ans + (g % MOD) * C[L + n - s][k - 2]) % MOD;
        }
    return ans;
};

