from itertools import combinations
class Solution:
    def sumOfPowers(self, nums: List[int], k: int) -> int:
        MOD = 10**9 + 7
        ans = 0
        for c in combinations(sorted(nums), k):
            ans += min(c[i + 1] - c[i] for i in range(k - 1))
        return ans % MOD

