    int kk; long long ans = 0; const long long MOD = 1e9 + 7;
    void rec(vector<int>& v, vector<int>& cur, int i) {
        if ((int)cur.size() == kk) {
            long long m = LLONG_MAX;
            for (int t = 1; t < kk; t++) m = min(m, (long long)cur[t] - cur[t - 1]);
            ans = (ans + m) % MOD;
            return;
        }
        if ((int)v.size() - i < kk - (int)cur.size()) return;
        rec(v, cur, i + 1);
        cur.push_back(v[i]); rec(v, cur, i + 1); cur.pop_back();
    }
    int sumOfPowers(vector<int>& nums, int k) {
        kk = k; sort(nums.begin(), nums.end());
        vector<int> cur; rec(nums, cur, 0);
        return ans;
    }
};

