class Solution {
    int kk; long ans = 0; final long MOD = 1_000_000_007L;
    void rec(int[] v, List<Integer> cur, int i) {
        if (cur.size() == kk) {
            long m = Long.MAX_VALUE;
            for (int t = 1; t < kk; t++) m = Math.min(m, (long) cur.get(t) - cur.get(t - 1));
            ans = (ans + m) % MOD;
            return;
        }
        if (v.length - i < kk - cur.size()) return;
        rec(v, cur, i + 1);
        cur.add(v[i]); rec(v, cur, i + 1); cur.remove(cur.size() - 1);
    }
    public int sumOfPowers(int[] nums, int k) {
        kk = k; Arrays.sort(nums);
        rec(nums, new ArrayList<>(), 0);
        return (int) ans;
    }
}

